#include <bits/stdc++.h>
using namespace std;

const int MAXN = 510;
int n, m, P, C[MAXN][MAXN], f1[MAXN], f2[MAXN][MAXN], g1[MAXN], g2[MAXN][MAXN];

int main() {
    scanf("%d %d %d", &n, &m, &P);
    for (int i = 0; i <= n; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P;
        }
    }
    f1[0] = 1;
    for (int i = 1; i <= n; i++) {
        f1[i] = 0;
        g1[i] = 0;
        for (int j = 1; j <= i; j++) {
            f1[i] = (f1[i] + (long long)f1[j - 1] * f1[i - j] % P * C[i - 1][j - 1]) % P;
            int t = ((long long)f1[j - 1] * g1[i - j] + (long long)g1[j - 1] * f1[i - j]) % P;
            t = (t * (i + 1)) % P;
            g1[i] = (g1[i] + ((long long)f1[j - 1] * f1[i - j] % P * (C[j][2] + C[i - j + 1][2]) + t) % P * C[i - 1][j - 1]) % P;
        }
        f1[i] = (long long)(i + 1) * f1[i] % P;
    }
    g2[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= min(i, m); j++) {
            f2[i][j] = f2[i - 1][j];
            g2[i][j] = g2[i - 1][j];
            for (int k = 1; k <= j; k++) {
                long long f_val = (i - k ? f2[i - k - 1][j - k] : 1);
                f2[i][j] = (f2[i][j] + f_val * f1[k] % P * C[j][k]) % P;
                long long g_val = (i - k ? f2[i - k - 1][j - k] : 1);
                long long g_part = ((long long)g_val * g1[k] + (long long)(i - k ? g2[i - k - 1][j - k] : 0) * f1[k]) % P;
                g2[i][j] = (g2[i][j] + g_part * C[j][k]) % P;
            }
        }
    }
    printf("%d\n", g2[n][m]);
    return 0;
}
